head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf60101";
scwin.div_slb_detail = null;
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $c.util.getComponent('slc_sriBndTpCd').setValue("" + dma_result.get("sri_bnd_appl_tp_cd") + "");
        await scwin.slbAddRow();
        scwin.sriBndTpCdChange();
        await $c.win.alert("2024년 5월 31일부터 ESG채권 등록신청서 양식이 변경되었습니다. 채권상장시스템 로그인 전 [업무서식 다운로드]의 신규 양식을 참조하시기 바랍니다.");

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf60101.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":9
        ,"mmenu":0
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf60101' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.div_slb_detail = $c.util.getComponent('div_slb_detail');
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf60101.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files'));
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf60101.btn_mpd_files_select_onclick' }); }
};

/**
 * @method
 * @name btn_mpd_files_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf60101.btn_mpd_files_del_onclick' }); }
};

