/**
 * @method
 * @name CheckReqInfo_Cellphone
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.CheckReqInfo_Cellphone = async function (fm) { try { const v = (fm && fm.getValue) ? fm.getValue() : (fm && fm.value != null ? fm.value : null); if (v == null || String(v) === '') { return true; } if (!$c.str.isMobilePhone(String(v))) { await $c.win.alert('휴대전화번호 형식을 확인해 주세요.'); return false; } return true; } catch (_e) { return true; } };

