/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name showSriBndRegList
 * @description show Sri Bnd Reg List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showSriBndRegList = async function () {
    $c.util.getComponent('dma_showSriBndRegListReq').set('method', "showSriBndRegList");
    await scwin.tx_fn_showSriBndRegList('/sri/sribnd.do');
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    if (!await scwin.checkData()) {
        return;
    } else {
        if (!await $c.win.confirm("신청하시겠습니까?")) {
            return false;
        }
    }
    $c.util.getComponent("dma_showSriBndRegListReq").set("apctTelNo", $c.util.getComponent('ipt_apctTelNo1').getValue()+ '-' + $c.util.getComponent('ipt_apctTelNo2').getValue()+ '-' + $c.util.getComponent('ipt_apctTelNo3').getValue());
    $c.util.getComponent("dma_showSriBndRegListReq").set("apctFaxNo", $c.util.getComponent('ipt_apctFaxNo1').getValue()+ '-' + $c.util.getComponent('ipt_apctFaxNo2').getValue()+ '-' + $c.util.getComponent('ipt_apctFaxNo3').getValue());
    $c.util.getComponent("dma_showSriBndRegListReq").set("encrypApctEmail", $c.util.getComponent('ipt_encrypApctEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypApctEmail2').getValue());
    $c.util.getComponent('dma_showSriBndRegListReq').set('method', "saveSriBndReg");
    await scwin.tx_fn_save();
    document.btn_save.setStyle("display", "none");
};

/**
 * @method
 * @name checkData
 * @description check Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkData = async function () {
    const fm = (document.SendForm || { elements: [] });
    const _now_time = dma_hiddenStore.get("areaNowTimer");
    const _isur_cd = $c.util.getComponent("dma_showSriBndRegListReq").get("isurCd");
    if (!applTmCheck('SRI_REG', _now_time, _isur_cd)) {
        return false;
    }
    let rowCnt = $("#tbl_file tr").length;
    for (let i = 0; i < rowCnt; i++) {
        if ($("input[name='attach_file_nm[" + i + "]']").val() === "") {
            const tempVal = $("input[name=attach_file_tp_cd]:eq(" + i + ")").val();
            if (tempVal === "5" || tempVal === "6" || tempVal === "7" || tempVal === "13" || tempVal === "17" || tempVal === "18") {
                await $c.win.alert("필수 파일을 선택하십시오.");
            } else {
                await $c.win.alert("기타 파일을 선택하십시오.");
            }
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
    }
    let file_size_sum = 0;
    const limitedSize = 200 * (1024 * 1024);
    for (let i = 0; i < rowCnt; i++) {
        file_size_sum += $("input[name='attachFiles[" + i + "]']")[0].files[0].size;
    }
    if (file_size_sum > limitedSize) {
        await $c.win.alert(" 최대 파일업로드 허용용량 200MB를 초과하였습니다. \n\n 현재 용량은 " + Math.round(file_size_sum / (1024 * 1024)) + "MB입니다.");
        return false;
    }
    const sri_bnd_tp_cd = $c.util.getComponent('slc_sriBndTpCd').getValue();
    if (sri_bnd_tp_cd === "4") {
        rowCnt = $("#tbl_slb tr").length;
        for (let i = 1; i <= rowCnt; i++) {
            if ($("#lst_observ_dd" + i).val() === "") {

            }
        }
    }
    if (!CheckReqInfo(fm)) {
        return false;
    } else {
        if (!await scwin.CheckReqInfo_Cellphone(fm)) {
            return false;
        }
    }
    return true;
};

/**
