    const strTd2 = "<td><div style='display:flex; align-items:center; justify-content:center'>" + "<select name='sri_bnd_chg_contn_cd'>" + "<option value=''>해당없음</option>" + "" + "<option value='${entity.cdId}'>${entity.cdVal}</option>" + "</select></div></td>";
    const strTd3 = "<td><div style='display:flex; align-items:center; justify-content:center'>" + "<input type='text' name='lst_observ_dd' id='lst_observ_dd" + newRowNum + "' value='' maxlength=8 class='txt input-calendar' title='날짜입력' onBlur='Chk_Date2( this,'최종관찰일자' )' onfocus='cal_offMask('document.SendForm.lst_observ_dd')' onkeyup='chkDate('document.SendForm.lst_observ_dd')' />";
    +"</div></td>";
