};

/**
 * @method
 * @name sriBndTpCdChange
 * @description sri Bnd Tp Cd Change 처리
 * @returns {void}
 * @hidden N
 */
scwin.sriBndTpCdChange = function () {
    const val = $c.util.getComponent('slc_sriBndTpCd').getValue();
    if (val === "4") {
        scwin.div_slb_detail.setStyle("display", "");
        $c.util.getComponent('slc_sriBndRefRuleTpCd').setValue("7");
    } else {
        scwin.div_slb_detail.setStyle("display", "none");
    }
    scwin.displayFileUploadList();
};

/**
 * @method
 * @name displayFileUploadList
 * @description display File Upload List 처리
 * @returns {void}
 * @hidden N
 */
scwin.displayFileUploadList = function () {
    const val = $c.util.getComponent('slc_sriBndTpCd').getValue();
    if (val === "4") {
        txt_fileTpSlb.setLabel("관리체계");
        txt_fileTpSlb2.setLabel("외부검토서류");
        scwin.addMandatoryFile();
        /* 수동 전환 필요: 이름 선택자 순회 [name=attach_file_tp_cd] — B3/B4 스펙 참조 없음(as-is 대조 필요) · to-be 에 돌 요소가 없다 */ $('input[name=attach_file_tp_cd]').each(function(i) {
                const tempVal = $("input[name=attach_file_tp_cd]:eq(" + i + ")").val();
                if (tempVal === "6") {
                    $("input[name=attach_file_tp_cd]:eq(" + i + ")").val("17");
                }
                if (tempVal === "7") {
                    $("input[name=attach_file_tp_cd]:eq(" + i + ")").val("18");
                }
        });
    } else {
        txt_fileTpSlb.setLabel("조달자금서류(관리체계)");
        txt_fileTpSlb2.setLabel("외부검토서류(대표자확인서)");
        scwin.delMandatoryFile();
        /* 수동 전환 필요: 이름 선택자 순회 [name=attach_file_tp_cd] — B3/B4 스펙 참조 없음(as-is 대조 필요) · to-be 에 돌 요소가 없다 */ $('input[name=attach_file_tp_cd]').each(function(i) {
                const tempVal = $("input[name=attach_file_tp_cd]:eq(" + i + ")").val();
                if (tempVal === "17") {
                    $("input[name=attach_file_tp_cd]:eq(" + i + ")").val("6");
                }
                if (tempVal === "18") {
                    $("input[name=attach_file_tp_cd]:eq(" + i + ")").val("7");
                }
        });
    }
    reNames();
};

