/**
 * @method
 * @name delMandatoryFile
 * @description del Mandatory File 처리
 * @returns {void}
 * @hidden N
 */
scwin.delMandatoryFile = function () {
    /* 수동 전환 필요: 이름 선택자 순회 [name=attach_file_tp_cd] — B3/B4 스펙 참조 없음(as-is 대조 필요) · to-be 에 돌 요소가 없다 */ $('input[name=attach_file_tp_cd]').each(function(i) {
            const tempVal = $("input[name=attach_file_tp_cd]:eq(" + i + ")").val();
            if (tempVal === "13") {
                const tblFile = $c.util.getComponent("tbl_file");
                tblFile.deleteRow(i);
            }
    });
};
